  "revision_action": "strengthen",
  "supportive_card_ids": ["C05","C06","C02","C01","C08","C18","C03","C43","C44","C64","C75"],
  "contradictory_card_ids": ["C14","C15","C16","C29"],
  "prediction_basis_card_ids": ["C05","C06","C02","C01","C08","C18","C43","C44","C64","C75"],
  "claims": [
    {
      "claim": "Fed-state and general human oral bioavailability records for small heteroaromatic drugs consistently exceed 20%: ziprasidone ~59–60% fed, trazodone 63–65% fed, urapidil 72–78%, teneligliptin 43–87%, eltrombopag 52%, and ondansetron 40% even under rifampin co-treatment.",
      "card_ids": ["C05","C06","C02","C01","C08","C18","C03"]
    },
    {
      "claim": "Human fraction-absorbed records for similar small lipophilic/neutral drugs show complete intestinal absorption (diazepam 100%, ketoprofen 100%), supporting no absorption barrier.",
      "card_ids": ["C43","C44"]
    },
    {
      "claim": "Gut-wall permeability records show high Papp and efflux ratios near 1 for the pyrazolone/heteroaromatic class; the closest analog edaravone (norantipyrine) had Papp >10×10^-6 cm/s in rat intestine/MDCKII, indicating no efflux barrier.",
      "card_ids": ["C64","C55","C56","C60","C65","C66"]
    },
    {
      "claim": "L6 hepatic-clearance records are predominantly for unrelated CYP2C19 substrates (mephenytoin variants, diazepam, meperidine); the only antipyrine-related record (C75) reports low intrinsic clearance of norantipyrine in human liver microsomes, providing no evidence of high first-pass loss.",
      "card_ids": ["C75","C69","C73","C77"]
    },
    {
      "claim": "Low or variable F records are structurally distant or condition-mismatched: TFMPP low was inferred from <1% urinary recovery, brexanolone <5% is a steroid, and mCPP ranged 12–108%/14–108% with wide variability; none provides affirmative transferable evidence for F<20%.",
      "card_ids": ["C14","C15","C16","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C67","C68","C69","C70","C71","C72","C73","C74","C75","C76","C77","C78"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "No query-specific fed-state pharmacokinetic or IV-comparator AUC data are provided.",
    "No query-specific hepatic clearance or metabolic stability measurement is available; L6 records are mostly for other molecules and C75 measures the norantipyrine metabolite rather than the parent.",
    "No query-specific intestinal metabolism or first-pass extraction data are available.",
    "No direct query-specific solubility/dissolution data under fed conditions are available.",
    "L3 oral AUC/Cmax records lack IV comparison and were not used as direct F evidence."
  ],
  "decision_summary": "Prediction remains high. The query is a small neutral pyrazolone with favorable absorption-related physicochemical properties; L4 human fraction-absorbed records show complete absorption for similar small lipophilic/neutral drugs, L5 gut-wall records show high permeability and no efflux barrier, and L6 provides no evidence of high hepatic first-pass loss (the only antipyrine-related record shows low intrinsic clearance of norantipyrine). Fed-state and general human F records for small heteroaromatic drugs consistently exceed 20%, while low-F records are structurally distant or condition-mismatched. Confidence remains moderate because no direct query-specific F measurement is available."
}

